cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and base premiums ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a plain sword (base 100 G) for a new customer as 115 G (100 + 10 first insurance + 5 fee)");
  it.todo("quotes a plain amulet (base 60 G) for a new customer as 71 G (60 + 6 first insurance + 5 fee)");
  it.todo("quotes a plain staff (base 80 G) for a new customer as 93 G (80 + 8 first insurance + 5 fee)");
  it.todo("quotes a plain potion (base 40 G) for a new customer as 49 G (40 + 4 first insurance + 5 fee)");
  it.todo("quotes a single rune (base 25 G) for a new customer as 33 G (25 + 2.5 first insurance = 27.5 -> rounded up 28 + 5 fee)");
  it.todo("quotes a single moonstone (base 25 G) for a new customer as 33 G");

  // --- Building block of 3 alike components ---
  it.todo("quotes 2 runes as base premium 50 G");
  it.todo("quotes 3 runes as base premium 60 G (block applies)");
  it.todo("quotes 4 runes as base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as base premium 175 G");
  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium (cursed sword base 100 G -> 150 G)");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5 (sword 100 G -> 130 G)");
  it.todo("adds no high-enchantment surcharge at enchantment 4 (sword stays 100 G)");
  it.todo("adds both curse and high-enchantment surcharges to a cursed sword with enchantment 5 (100 -> 180 G)");
  it.todo("applies item-specific surcharges only to the affected item: cursed sword + plain amulet -> 210 G before policy modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 10 % first insurance surcharge to the policy base premium of every quote");
  it.todo("applies a 15 % follow-up discount to every contract after the customer's first");
  it.todo("applies no follow-up discount to the customer's first contract");
  it.todo("adds the 5 G processing fee at the very end");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Integration examples ---
  it.todo("quotes a newcomer's cursed sword (0 years, first contract) as 165 G");
  it.todo("quotes a long-standing customer's second contract cursed sword with enchantment 7 (3 years) as 160 G");

  // --- Quote errors ---
  it.todo("throws an Error when a quote contains an item with an unknown type (e.g. broomstick)");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a policy covering a sword and an amulet at 3200 G (insurance sum 1600 G)");
  it.todo("caps a cursed sword policy at 2000 G -- premium modifiers do not raise the cap");
  it.todo("computes the insurance sum of a sword and 3 runes as 1750 G -- the block discount does not lower the sum");
  it.todo("caps a policy covering two swords at 4000 G (insurance sum 2000 G)");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays 400 G for 500 G damage to a regular sword (steel, enchantment 3) -- full reimbursement minus 100 G deductible");
  it.todo("pays 100 G for 200 G damage to a rune -- runes have no enchantment or material, so no special clause applies");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -> payout 600 G");
  it.todo("treats two damage entries of the same item type as separate damages with their own deductible");

  // --- Claim: special clauses ---
  it.todo("reimburses 50 % of the damage at enchantment exactly 8: dragon sword, damage 1000 G -> payout 400 G");
  it.todo("reimburses a dragon-material sword with enchantment 9, damage 1000 G, at 400 G (50 % rule wins, then deductible)");
  it.todo("reimburses a dragon-material sword with enchantment 5, damage 800 G, at 700 G (full reimbursement, then deductible)");
  it.todo("reimburses a steel sword with enchantment 9, damage 1000 G, at 400 G (50 % first, then deductible)");

  // --- Claim: cap exhaustion across claims ---
  it.todo("pays 1400 G on a first 1500 G claim against a sword policy, leaving cap 600 G");
  it.todo("reduces a second 1500 G claim to the remaining cap: payout 600 G, remaining cap 0 G");

  // --- Claim: payout rounding ---
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");

  // --- Claim errors ---
  it.todo("throws an Error when a damage entry references an item type not covered by the policy (amulet damaged, only sword insured)");
  it.todo("throws an Error when a damage entry references an unknown item type");
  it.todo("throws an Error when the damages contain more entries of a type than the policy covers (two sword damages, one sword insured)");
  it.todo("throws an Error when a damage entry has a negative amount (-200)");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} in step order to stdout");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for an unknown item type, writing no results to stdout");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for a rejected claim");
});
EOF
