const PROCESSING_FEE = 5;
const FIRST_INSURANCE_PERCENT = 10;
const PERCENT = 100;

const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };

const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;
const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
const HIGH_ENCHANTMENT_LEVEL = 5;

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function componentGroupPremium(type: string, count: number): number {
  return count === BLOCK_SIZE ? BLOCK_PREMIUM : count * BASE_PREMIUMS[type];
}

/** Alike components are counted per type; a group of exactly three is offered as a block. */
function componentsBasePremium(components: Item[]): number {
  const countsByType = new Map<string, number>();
  for (const component of components) {
    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
  }
  return [...countsByType].reduce((sum, [type, count]) => sum + componentGroupPremium(type, count), 0);
}

export function policyBasePremium(items: Item[]): number {
  const mainPremium = items
    .filter((item) => !isComponent(item))
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  return mainPremium + componentsBasePremium(items.filter(isComponent));
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function itemSurchargeRate(item: Item): number {
  const curse = item.cursed === true ? CURSE_SURCHARGE : 0;
  return curse + (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
}

/** Item-specific surcharges apply to the base premium of the affected item only. */
export function insuredItemsPremium(items: Item[]): number {
  const surcharges = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type] * itemSurchargeRate(item),
    0,
  );
  return policyBasePremium(items) + surcharges;
}

/** Premium amounts are kept as exact hundredths of a G until the final rounding. */
function quotePremium(items: Item[]): number {
  const baseHundredths = policyBasePremium(items) * PERCENT;
  const withSurcharge = baseHundredths + (baseHundredths * FIRST_INSURANCE_PERCENT) / PERCENT;
  return Math.ceil(withSurcharge / PERCENT + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): unknown[] {
  return scenario.steps.map((step) => ({ premium: quotePremium(step.items) }));
}

