function settleClaim(policy: Policy, damages: Damage[]): { payout: number; remainingCap: number } {
  const claimed = damages.reduce((sum, damage) => sum + damagePayout(damage), 0);
  const payout = Math.floor(withinRemainingCap(claimed, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}''')
