const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;
const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_DISCOUNT_RATE = 0.15;
const PERCENT = 100;
/**
 * All amounts are rounded to whole G in the MHPCO's favor: premiums up, payouts down.
 * Intermediate amounts stay fractional so that only the final amount is rounded.
 */
const roundPremiumInMHPCOFavour = Math.ceil;
const roundPayoutInMHPCOFavour = Math.floor;

const DEDUCTIBLE = 100;
const CAP_MULTIPLE = 2;
const REDUCED_REIMBURSEMENT = 0.5;
const REDUCED_REIMBURSEMENT_LEVEL = 8;

interface PriceListEntry {
  insuranceValue: number;
  basePremium: number;
}

/** The MHPCO price list: it defines both what is insurable and at what value and premium. */
const PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
  rune: { insuranceValue: 250, basePremium: 25 },
  moonstone: { insuranceValue: 250, basePremium: 25 },
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;
const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
const HIGH_ENCHANTMENT_LEVEL = 5;

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

/** The MHPCO insures only the item types on its price list. */
function priceListEntry(type: string): PriceListEntry {
  const entry = PRICE_LIST[type];
  if (entry === undefined) {
    throw new Error(`MHPCO does not insure items of type "${type}"`);
  }
  return entry;
}

function basePremiumOf(type: string): number {
  return priceListEntry(type).basePremium;
}

/** The insurance sum is the unmodified insured value of every item on the policy. */
export function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + priceListEntry(item.type).insuranceValue, 0);
}

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function componentGroupPremium(type: string, count: number): number {
  return count === BLOCK_SIZE ? BLOCK_PREMIUM : count * basePremiumOf(type);
}

/** Alike components are counted per type; a group of exactly three is offered as a block. */
function componentsBasePremium(components: Item[]): number {
  const countsByType = new Map<string, number>();
  for (const component of components) {
    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
  }
  return [...countsByType].reduce((sum, [type, count]) => sum + componentGroupPremium(type, count), 0);
}

export function policyBasePremium(items: Item[]): number {
  const mainPremium = items
    .filter((item) => !isComponent(item))
    .reduce((sum, item) => sum + basePremiumOf(item.type), 0);
  return mainPremium + componentsBasePremium(items.filter(isComponent));
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function itemSurchargeRate(item: Item): number {
  const curse = item.cursed === true ? CURSE_SURCHARGE : 0;
  return curse + (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
}

/** Item-specific surcharges are rated on the base premium of the affected item only. */
function itemSurcharges(items: Item[]): number {
  return items.reduce((sum, item) => sum + basePremiumOf(item.type) * itemSurchargeRate(item), 0);
}

export function insuredItemsPremium(items: Item[]): number {
  return policyBasePremium(items) + itemSurcharges(items);
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function policyModifierRate(customer: Customer, previousContracts: number): number {
  const loyalty = isLongStandingCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0;
  const followUp = previousContracts > 0 ? -FOLLOW_UP_DISCOUNT_RATE : 0;
  return FIRST_INSURANCE_RATE + loyalty + followUp;
}

/** Amounts are kept as exact hundredths of a G so that only the final premium is rounded. */
function quotePremium(items: Item[], customer: Customer, previousContracts: number): number {
  const baseHundredths = policyBasePremium(items) * PERCENT;
  const policyModifiers = baseHundredths * policyModifierRate(customer, previousContracts);
  const surcharges = itemSurcharges(items) * PERCENT;
  return roundPremiumInMHPCOFavour((baseHundredths + surcharges + policyModifiers) / PERCENT + PROCESSING_FEE);
}

/** Damage to strongly enchanted items is reimbursed at half; a deductible applies per damage event. */
function reimbursementRate(item: Item): number {
  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_LEVEL ? REDUCED_REIMBURSEMENT : 1;
}

/** The MHPCO does not accept a damage report for a negative amount. */
function reportedDamage(damage: Damage): number {
  if (damage.amount < 0) {
    throw new Error(`A damage amount cannot be negative, but was ${damage.amount}`);
  }
  return damage.amount;
}

function damagePayout(damage: Damage, item: Item): number {
  return Math.max(0, reportedDamage(damage) * reimbursementRate(item) - DEDUCTIBLE);
}

interface DamagedItem {
  damage: Damage;
  insured: Item;
}

interface Policy {
  items: Item[];
  remainingCap: number;
}

/** The total payout per policy is capped at twice the insurance sum. */
function withinRemainingCap(claimed: number, remainingCap: number): number {
  return Math.min(claimed, remainingCap);
}

/**
 * A claim is honoured only for items the policy covers, and each damage entry is
 * settled against a distinct insured item.
 */
function assignDamagesToInsuredItems(policy: Policy, damages: Damage[]): DamagedItem[] {
  const unclaimed = [...policy.items];
  return damages.map((damage) => {
    const position = unclaimed.findIndex((item) => item.type === damage.itemType);
    if (position < 0) {
      throw new Error(`The policy does not cover a further item of type "${damage.itemType}"`);
    }
    return { damage, insured: unclaimed.splice(position, 1)[0] };
  });
}

function settleClaim(policy: Policy, damages: Damage[]): { payout: number; remainingCap: number } {
  const claimed = assignDamagesToInsuredItems(policy, damages).reduce(
    (sum, { damage, insured }) => sum + damagePayout(damage, insured),
    0,
  );
  const payout = roundPayoutInMHPCOFavour(withinRemainingCap(claimed, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

export function runScenario(scenario: Scenario): unknown[] {
  const policies = new Map<number, Policy>();
  return scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      return settleClaim(policies.get(step.policy) as Policy, step.incident.damages);
    }
    const premium = quotePremium(step.items, scenario.customer, policies.size);
    policies.set(index, { items: step.items, remainingCap: insuranceSum(step.items) * CAP_MULTIPLE });
    return { premium };
  });
}

